CATEGORY_NAMES = {
    "space": "Sky and Space", "earth": "Our Planet", "weather": "Weather",
    "ocean": "The Ocean", "habitats": "Animal Habitats", "animals": "Animals",
    "plants": "Growing Things", "food": "Food and Cooking", "home": "Everyday Home",
    "vehicles": "Vehicles", "community": "Community Helpers", "arts": "Art and Music",
    "language": "Words and Numbers", "skills": "Kindness and Skills",
    "places": "Places to Explore",
}
CONTEXTS = {}
for row in RAW_CONTEXTS:
    category, slug, item_text = row.split("|")
    items = tuple(item_text.split(";"))
    if slug in CONTEXTS or len(items) != 5 or len(set(items)) != 5:
        raise ValueError("Invalid context: " + row)
    CONTEXTS[slug] = (category, slug.replace("_", " ").title(), items)

if len(CONTEXTS) != 150:
    raise ValueError("Expected exactly 150 new contexts")


def make_context_story(topic, seed, Scene):
    """Seven-scene vocabulary adventure: intro, five distinct words, finish."""
    category, title, items = CONTEXTS[topic]
    rng = random.Random(seed)
    hero = rng.choice(("Bibi Bunny", "Pip Puppy", "Mimi Kitten", "Toto Bear"))
    landscape = rng.choice(("the Rainbow Meadow", "the Sunny Valley", "the Starry Garden"))
    scenes = [
        Scene("intro", title.upper(),
              f"Hello, I'm {hero}! Welcome to {title}. Let's discover five words from {CATEGORY_NAMES[category]} together!")
    ]
    phrases = (
        "First, let's meet {word}! Can you say {word} with me?",
        "Next is {word}. Listen to the word, then say it aloud: {word}!",
        "Our third discovery is {word}! Let's remember that one.",
        "Here's {word}. That's our fourth discovery. Nice work!",
        "Last, we found {word}! Say it one more time: {word}!",
    )
    for i, word in enumerate(items):
        scenes.append(
            Scene("context", word.upper(), phrases[i].format(word=word),
                  word, i + 1, visual_category=category)
        )
    scenes.append(
        Scene("finish", "FIVE NEW WORDS!",
              f"We explored {title} and learned five words! Which one was your favorite? See you soon!")
    )
    return hero, landscape, title, scenes
